SPEC = [
    ('grammar', 'EBNF Grammar', '<h2>Chương trình</h2>\n<pre><code>program    = { statement } ;\nstatement  = let_stmt | assign_stmt | print_stmt | listen_stmt\n           | fn_stmt | return_stmt | if_stmt | while_stmt\n           | each_stmt | try_stmt | stop_stmt | skip_stmt\n           | class_stmt | enum_stmt | expr_stmt ;\n\nlet_stmt   = "paw" IDENT "=" expr NEWLINE ;\nprint_stmt = "meow" expr NEWLINE ;\nfn_stmt    = "purr" IDENT [ params ] NEWLINE INDENT { stmt } DEDENT ;\nif_stmt    = "sniff" expr NEWLINE INDENT { stmt } DEDENT\n             [ "swat" NEWLINE INDENT { stmt } DEDENT ] ;\nwhile_stmt = "knead" expr NEWLINE INDENT { stmt } DEDENT ;\neach_stmt  = "groom" IDENT "of" expr NEWLINE INDENT { stmt } DEDENT ;\ntry_stmt   = "tap" NEWLINE INDENT { stmt } DEDENT\n             [ "hiss" [ IDENT ] NEWLINE INDENT { stmt } DEDENT ] ;\nclass_stmt = "cat" IDENT [ "kin" IDENT ] NEWLINE INDENT { member } DEDENT ;\nenum_stmt  = "litter" IDENT NEWLINE INDENT { IDENT NEWLINE } DEDENT ;</code></pre>\n<h2>Biểu thức</h2>\n<pre><code>expr     = or_expr ;\nor_expr  = and_expr { "either" and_expr } ;\nand_expr = not_expr { "with" not_expr } ;\nnot_expr = "never" not_expr | cmp_expr ;\ncmp_expr = add_expr { cmp_op add_expr } ;\nadd_expr = mul_expr { ("+" | "-") mul_expr } ;\nmul_expr = unary { ("*" | "/" | "%") unary } ;\nprimary  = NUMBER | STRING | "nod" | "shake" | "hungry"\n         | IDENT | "me" | "(" expr ")" | list_lit\n         | dict_lit | lambda ;\nlambda   = "kit" "(" [ params ] ")" "=>" expr ;</code></pre>\n'),
    ('semantics', 'Semantics', '<h2>Đánh giá biểu thức</h2>\n<p>Trái sang phải, tôn trọng độ ưu tiên:</p>\n<ol>\n<li>()</li>\n<li>never, dấu âm</li>\n<li>* / %</li>\n<li>+ -</li>\n<li>&lt; &gt; &lt;= &gt;=</li>\n<li>== !=</li>\n<li>with</li>\n<li>either</li>\n</ol>\n<h2>Short-circuit evaluation</h2>\n<pre><code>a with b    # a sai → không đánh giá b\na either b  # a đúng → không đánh giá b</code></pre>\n<h2>Ép kiểu</h2>\n<ul>\n<li>+ với chuỗi → ép vế còn lại thành chuỗi</li>\n<li>Các phép khác yêu cầu cả hai là số</li>\n<li>So sánh không ép: 42 == "42" là shake</li>\n</ul>\n<h2>Truthiness</h2>\n<ul>\n<li>nod → đúng, shake → sai</li>\n<li>Số khác 0 → đúng</li>\n<li>String/DS khác rỗng → đúng</li>\n<li>hungry → sai</li>\n</ul>\n<h2>Scope</h2>\n<ul>\n<li>Mỗi hàm có scope riêng</li>\n<li>Biến trong hàm nhìn thấy biến ngoài (lexical scope)</li>\n<li>Not có từ khóa global</li>\n</ul>\n'),
    ('conventions', 'Code conventions', '<h2>Đặt tên</h2>\n<table>\n<tr><th>Loại</th><th>Kiểu</th><th>Example</th></tr>\n<tr><td>Biến</td><td>snake_case</td><td><code>cat_name</code></td></tr>\n<tr><td>Function</td><td>snake_case</td><td><code>find_max</code></td></tr>\n<tr><td>Hằng</td><td>UPPER</td><td><code>MAX_SPEED</code></td></tr>\n<tr><td>Class</td><td>PascalCase</td><td><code>Point</code></td></tr>\n</table>\n<h2>Thụt lề</h2>\n<p>4 spaces, không tab, không trộn.</p>\n<h2>Độ dài dòng</h2>\n<p>Tối đa 80 ký tự.</p>\n<h2>Comment</h2>\n<p>Giải thích <b>tại sao</b>, không phải <b>làm gì</b>.</p>\n'),
]
